(()=>{'use strict';const subjects={I:['I',false],you:['You',false],we:['We',false],they:['They',false],Maya:['Maya',true],Leo:['Leo',true]},verbs={study:['study','studies','biology'],read:['read','reads','books'],have:['have','has','a library card']};
function sentence(subject,verb,form){const[s,singular]=subjects[subject],[base,third,object]=verbs[verb],aux=singular?'does':'do';let result;if(form==='statement')result=s+' '+(singular?third:base)+' '+object+'.';else if(form==='negative')result=s+' '+aux+' not '+base+' '+object+'.';else if(form==='question')result=(singular?'Does':'Do')+' '+(subject==='I'?'I':s==='You'?'you':s==='We'?'we':s==='They'?'they':s)+' '+base+' '+object+'?';else result='Where '+aux+' '+(subject==='I'?'I':s==='You'?'you':s==='We'?'we':s==='They'?'they':s)+' '+base+' '+object+'?';return{sentence:result,explanation:form==='statement'?(singular?'The singular subject selects the third-person main-verb form.':'This subject selects the base main-verb form.'):'The auxiliary '+aux+' carries agreement; the main verb remains '+base+'.'};}
if(typeof module!=='undefined'){module.exports={sentence};return;}const f=document.getElementById('routine-form');const update=()=>{const r=sentence(f.elements.subject.value,f.elements.verb.value,f.elements.form.value);document.getElementById('routine-sentence').textContent=r.sentence;document.getElementById('routine-explanation').textContent=r.explanation;};f.addEventListener('change',update);update();})();
